import{_ as e,c as l,o as i,ah as r}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"澤火革","description":"周易折中 - 澤火革","frontmatter":{"title":"澤火革","description":"周易折中 - 澤火革"},"headers":[],"relativePath":"classics/zhezhong/055.md","filePath":"classics/zhezhong/055.md"}'),h={name:"classics/zhezhong/055.md"};function p(n,a,d,t,s,o){return i(),l("div",null,[...a[0]||(a[0]=[r('<h1 id="澤火革" tabindex="-1">澤火革 <a class="header-anchor" href="#澤火革" aria-label="Permalink to “澤火革”">​</a></h1><h3 id="程傳" tabindex="-1">程傳 <a class="header-anchor" href="#程傳" aria-label="Permalink to “程傳”">​</a></h3><p>〈革序卦〉：“井道不可不革，故受之以革。井之為物，存之則穢敗，易之則清潔，不可不革者也。故井之後，受之以革也。為卦兌上離下，澤中有火也。革，變革也。水火相息之物，水滅火，火涸水，相變革者也。火之性上，水之性下，若相違行，則睽而已；乃火在下，水在上，相就而相剋相滅息者也，所以為革也。又二女同居，而其歸各異，其志不同，為不相得也，故為革也。”</p><p>革：已日乃孚，元亨利貞，悔亡</p><h3 id="本義" tabindex="-1">本義 <a class="header-anchor" href="#本義" aria-label="Permalink to “本義”">​</a></h3><p>革，變革也。兌澤在上，離火在下，火燃則水乾，水決則火滅。中少二女，合為一卦，而少上中下志不相得，故其卦為革也。變革之初，人未之信，故必已日而後信。又以其內有文明之徳，而外有和說之氣，故其佔為有所更革，皆大亨而得其正。所革皆當，而所革之悔亡也。一有不正則所革不信、不通，而反有悔矣。</p><h3 id="程傳-1" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-1" aria-label="Permalink to “程傳”">​</a></h3><p>革者，變其故也。變其故，則人未能遽信，故必已日然後人心信從。元亨利貞，悔亡，斃壊而後革之，革之所以致其通也。故革之而可以大亨，革之而利於正道，則可久而得去故之義無變動之悔，乃悔亡也。革而無甚益，猶可悔也，況反害乎？古人所以重改作也。</p><h3 id="集說" tabindex="-1">集說 <a class="header-anchor" href="#集說" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>李氏簡曰 ：已日者，已可革之時也。先時而革，則人疑而罔孚，故已日乃孚。元亨利貞者，謂窮則變，固有大通之道，而利於不失正也。正則其悔亡矣。</p></li><li><p>何氏楷曰 ：已日即六二所謂已日也，乃孚即九三九四九五所謂有孚也，悔亡即九四所謂悔亡也。所以雲已日者，變革天下之事不當輕遽，乃能孚信於人，乃難辭也。下三爻方欲革故而為新，故有謹重不輕革之意；上三爻則故者已革而為新矣。九四當上下卦之交，正改命之時，故悔亡獨於九四見之，即彖傳所云“革而當，其悔乃亡”也。</p></li></ul><h3 id="案" tabindex="-1">案 <a class="header-anchor" href="#案" aria-label="Permalink to “案”">​</a></h3><p>已日乃孚，李氏、何氏之說為長。蓋卦辭、爻辭不應互異也。</p><p>象曰：澤中有火，革；君子以治歷明時</p><h3 id="本義-1" tabindex="-1">本義 <a class="header-anchor" href="#本義-1" aria-label="Permalink to “本義”">​</a></h3><p>四時之變革之大者。</p><h3 id="程傳-2" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-2" aria-label="Permalink to “程傳”">​</a></h3><p>水火相息為革，革變也。君子觀變革之象，推日月星辰之遷易，以治歷數，明四時之序也。夫變易之道，事之至大，理之至明，跡之至著，莫如四時。觀四時而順變革，則與天地合其序矣。</p><h3 id="集說-1" tabindex="-1">集說 <a class="header-anchor" href="#集說-1" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>虞氏翻曰 ：曆象謂日月星辰也。天地革而四時成，故君子以治歷明時也。</p></li><li><p>朱子語類雲 ：治歷明時，非謂歷當改革，蓋四時變革中便有個治歷明時底道理。</p></li></ul><p>彖曰：革，水火相息，二女同居，其志不相得曰革</p><h3 id="本義-2" tabindex="-1">本義 <a class="header-anchor" href="#本義-2" aria-label="Permalink to “本義”">​</a></h3><p>以卦象釋卦名義。大略與睽相似，然以相違而為睽，相息而為革也。息滅，息也，又為生息之義。滅息而後生息也。</p><h3 id="程傳-3" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-3" aria-label="Permalink to “程傳”">​</a></h3><p>澤火相滅息，又二女志不相得，故為革。息為止息，又為生息，物止而後有生，故為生義。革之相息，謂止息也。</p><h3 id="集說-2" tabindex="-1">集說 <a class="header-anchor" href="#集說-2" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>朱氏震曰 ：兌澤離火，而彖曰“水火”，何也？曰坎兌一也。澤者，水所鍾，無水則無澤矣。坎上為雲，下為雨。上為雲者，澤之氣也；下為雨，則澤萬物也。故屯、需之坎為雲，小畜之兌亦為雲。坎為川，大畜之兌亦為川。坎為水，革兌亦為水。坎陽兌陰，陰陽二端，其理則一。知此始可言象矣。</p></li><li><p>朱子語類雲 ：革之象不曰“澤在火上”，而曰“澤中有火”。蓋水在火上，則水滅了火，不見得火炎則水涸之義。澤中有火，則二物並在，有相息之象。</p></li><li><p>李氏舜臣曰 ：不同行不過，有相離之意，故止於睽；不相得，則不免有相剋之事故，至於革。</p></li><li><p>胡氏炳文曰 ：既濟水在火上，不曰相息者何也？坎之水動水也，火不能息之；澤之水止水也，止水在上而火炎上，故息。</p></li></ul><p>已日乃孚，革而信之；文明以說，大亨以正，革而當，其悔乃亡</p><h3 id="本義-3" tabindex="-1">本義 <a class="header-anchor" href="#本義-3" aria-label="Permalink to “本義”">​</a></h3><p>以卦德釋卦辭。</p><h3 id="程傳-4" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-4" aria-label="Permalink to “程傳”">​</a></h3><p>事之變革，人心豈能便信？必終日而後孚。在上者於改為之際，當詳告申令，至於已日，使人信之。人心不信，雖強之行，不能成也。先王政令，人心始以為疑者有矣，然其久也必信。終不孚而成善治者，未之有也。文明以說，以卦才言革之道也。離為文明，兌為說。文明則理無不盡，事無不察；說則人心和順。革而能照察事理，和順人心，可致大亨而得貞正。如是變革得其至當，故悔亡也。天下之事，革之不得其道，則反致弊害。故革有悔之道，唯革之至當，則新舊之悔皆亡也。</p><h3 id="集說-3" tabindex="-1">集說 <a class="header-anchor" href="#集說-3" aria-label="Permalink to “集說”">​</a></h3><ul><li>胡氏炳文曰 ：彖未有言悔亡者，唯革言之。革易有悔也，必革而當，其悔乃亡。“當”字即是“貞”字。一有不貞，則有不信、有不通，皆不當者也。</li></ul><h3 id="案-1" tabindex="-1">案 <a class="header-anchor" href="#案-1" aria-label="Permalink to “案”">​</a></h3><p>“文明以說，大亨以正”兩以字，上句重在“文明”，蓋至明則事理周盡，故以此而順人心，有所更改則無不宜也；下句重在“正”，蓋其大亨也以正行之，則無不順也。凡彖傳用“以”字者，文體正倒皆可互用，如“順以動”及“動而以順”行，其義一也。</p><p>天地革而四時成，湯武革命，順乎天而應乎人，革之時大矣哉</p><h3 id="本義-4" tabindex="-1">本義 <a class="header-anchor" href="#本義-4" aria-label="Permalink to “本義”">​</a></h3><p>極言而贊其大。</p><h3 id="程傳-5" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-5" aria-label="Permalink to “程傳”">​</a></h3><p>推革之道，極乎天地變易，時運終始也。天地陰陽推遷變易而成四時萬物，於是生長成終，各得其宜。革而後四時成也。時運既終，必有革而新之者。王者之興，受命於天，故易世謂之革命。湯武之王，上順天命，下應人心，順乎天而應乎人也。天道變改，世故遷易，革之至大也。故贊之曰：“革之時大矣哉！”</p><h3 id="集說-4" tabindex="-1">集說 <a class="header-anchor" href="#集說-4" aria-label="Permalink to “集說”">​</a></h3><ul><li>朱子語類雲 ：革是更革之謂，到這裡須盡翻轉更變一番。所謂上下與天地同流，豈曰小補之哉？小補之者，謂扶衰救弊，逐些補緝，如錮露家事相似。若是更革，則須徹底從新鑄造一番，非止補其罅漏而已。</li></ul><p>初九：鞏用黃牛之革</p><h3 id="本義-5" tabindex="-1">本義 <a class="header-anchor" href="#本義-5" aria-label="Permalink to “本義”">​</a></h3><p>雖當革時，居初無應，未可有為，故為此象。鞏固也。黃，中色；牛，順物。革所以固物，亦取卦名而義不同也。其佔為當堅確固守，而不可以有為。聖人之於變革，其謹如此。</p><h3 id="程傳-6" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-6" aria-label="Permalink to “程傳”">​</a></h3><p>變革事之大也，必有其時、有其位、有其才。審慮而慎動，而後可以無悔。九以時則初也，動於事初，則無審慎之意，而有躁易之象。以位則下也，無時無援而動於下，則有僭妄之咎，而無體勢之重。以才則離體而陽也，離性上而剛，體健皆速於動也。其才如此，有為則兇咎至矣。蓋剛不中而體躁，所不足者中與順也。當以中順自固，而無妄動則可也。鞏，局束也；革，所以包束。黃，中色；牛，順物。鞏用黃牛之革，謂以中順之道自固，不妄動也。不雲吉凶何也？曰妄動則有兇咎，以中順自固，則不革而已，安得便有吉凶乎？</p><h3 id="集說-5" tabindex="-1">集說 <a class="header-anchor" href="#集說-5" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>幹氏寶曰 ：在革之初，未可以動，故曰“鞏用黃牛之革”。</p></li><li><p>劉氏牧曰 ：下非可革之位，初非可革之時，要在固守中順之道而不敢有革也。</p></li><li><p>呂氏大臨曰 ：初九當革之初，居下無位，比於六二，上無正應，雖有剛徳不當自任，惟結六二以自固，故“鞏用黃牛之革”。六二居中柔順，故曰“黃牛”，與遁六二同義。</p></li><li><p>龔氏煥曰 ：《易》言“黃牛之革”者二，遁之六二居中有應，欲遁而不可遁者也；革之初九在下無應，當革而不可革者也。所指雖殊，而意實相類。案：更改之義有取於革者，革鳥獸之皮也。鳥獸更四時，則皮毛改換，堯典“希革毛毨”之類是也。六爻取象於牛虎豹者以此。牛之皮至堅韌，難以更革者也。以之系物則固，故遁二之“執用”者似之；以之裹物則密，故革初之“鞏用”者似之。</p></li></ul><p>象曰：鞏用黃牛，不可以有為也</p><h3 id="程傳-7" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-7" aria-label="Permalink to “程傳”">​</a></h3><p>以初九時位才皆不可以有為，故當以中順自固也。</p><h3 id="集說-6" tabindex="-1">集說 <a class="header-anchor" href="#集說-6" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>胡氏瑗曰 ：凡革之道，必須已日然後可以革之也。民固即日而未孚，可遽革之乎？故但可固守中順，未可大有所為。</p></li><li><p>鄭氏汝諧曰 ：居位之下，革之而人未必從。當革之始，遽革而人未必信。固執中順之道，循理而變通可也。自我有為，不可也。於革之初言之，欲其謹於始也。</p></li></ul><p>六二：已日乃革之，徵吉，無咎</p><h3 id="本義-6" tabindex="-1">本義 <a class="header-anchor" href="#本義-6" aria-label="Permalink to “本義”">​</a></h3><p>六二柔順中正，而為文明之主，有應於上，於是可以革矣。然必已日然後革之，則徵吉而無咎。戒佔者猶未可遽變也。</p><h3 id="程傳-8" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-8" aria-label="Permalink to “程傳”">​</a></h3><p>以六居二，柔順而得中正，又文明之主，上有剛陽之君，同徳相應。中正則無偏蔽，文明則盡事理，應上則得權勢，體順則無違悖。時可矣，位得矣，才足矣，處革之至善者也。然臣道不當為革之先，又必待上下之信，故已日乃革之也。如二之才徳所居之地，所逢之時，足以革天下之弊，新天下之治，當進而上輔於君，以行其道，則吉而無咎也。不進則失可為之時，為有咎也。以二體柔而處當位，體柔則其進緩，當位則其處固。變革者事之大，故有此戒。二得中而應剛，未至失於柔也。聖人因其有可戒之疑而明其義耳，使賢才不失可為之時也。</p><h3 id="集說-7" tabindex="-1">集說 <a class="header-anchor" href="#集說-7" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>王氏宗傳曰 ：六二以中正之徳，上應九五中正之君，當革之時，卦徳所謂“已日乃孚”是也。故曰“已日乃革之，徵吉無咎”。</p></li><li><p>熊氏良輔曰 ：六二為內卦之主，故卦辭之“已日”見之於此。卦曰“已日乃孚”，爻曰“已日乃革”者，孚而後革也。</p></li></ul><p>象曰：已日革之，行有嘉也</p><h3 id="程傳-9" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-9" aria-label="Permalink to “程傳”">​</a></h3><p>已日而革之，徵則吉而無咎者，行則有嘉慶也。謂可以革天下之弊，新天下之事。處而不行，是無救弊濟世之心，失時而有咎也。</p><h3 id="集說-8" tabindex="-1">集說 <a class="header-anchor" href="#集說-8" aria-label="Permalink to “集說”">​</a></h3><ul><li>俞氏琰曰 ：未當革而遽往，適以滋弊耳，何嘉之有？必往於已日，當革之時，則其行有嘉美之功。行釋徵字，嘉釋吉無咎。</li></ul><p>九三：徵兇，貞厲，革言三就，有孚</p><h3 id="本義-7" tabindex="-1">本義 <a class="header-anchor" href="#本義-7" aria-label="Permalink to “本義”">​</a></h3><p>過剛不中，居離之極，躁動於革者也。故其佔有“徵兇貞厲”之戒。然其時則當革，故至於“革言三就”，則亦有孚而可革也。</p><h3 id="程傳-10" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-10" aria-label="Permalink to “程傳”">​</a></h3><p>九三以剛陽為下之上，又居離之上而不得中，躁動於革者也。在下而躁於變革，以是而行，則有兇也。然居下之上，事苟當革，豈可不為也？在乎守貞正而懐危懼，順從公論，則可行之不疑。革言，猶當革之論；就成也，合也。審察當革之言，至於三而皆合，則可信也。言重慎之至，能如是，則必得至當，乃有孚也。已可信而眾所信也，如此則可以革矣。在革之時，居下之上，事之當革，若畏懼而不為，則失時為害；唯當慎重之至，不自任其剛明，審稽公論，至於三就而後革之，則無過矣。</p><h3 id="集說-9" tabindex="-1">集說 <a class="header-anchor" href="#集說-9" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>呂氏大臨曰 ：九三居下體之上，自初至三，遍行三爻，革之有漸，革道以成，故曰“革言三就”。至於三，則民信之矣，故有孚。</p></li><li><p>龔氏煥曰 ：九三以過剛之才，躁動以往，則兇。處當革之時，貞固自守，則厲。惟於改革之言，詳審三就，則既無躁動之兇，又無固守之厲，得其時宜，所以可革也。</p></li><li><p>胡氏炳文曰 ：以其過剛也，故恐其徵而不已則兇；以其不中也，又恐其一於貞固而失變革之義，則厲。故必革之言至於三就，審之屢，則有孚而可革矣。</p></li></ul><p>象曰：革言三就，又何之矣</p><h3 id="本義-8" tabindex="-1">本義 <a class="header-anchor" href="#本義-8" aria-label="Permalink to “本義”">​</a></h3><p>言已審。</p><h3 id="程傳-11" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-11" aria-label="Permalink to “程傳”">​</a></h3><p>稽之眾論，至於三就，事至當也。又何之矣，乃俗語“更何往也”。如是而行，乃順理時行，非已之私意所欲為也，必得其宜矣。</p><h3 id="集說-10" tabindex="-1">集說 <a class="header-anchor" href="#集說-10" aria-label="Permalink to “集說”">​</a></h3><ul><li>徐氏幾曰 ：初未可革，二乃革之，三則變革之事成矣。凡事詳審至再至三，則止矣，又何往焉。</li></ul><p>九四：悔亡，有孚，改命吉</p><h3 id="本義-9" tabindex="-1">本義 <a class="header-anchor" href="#本義-9" aria-label="Permalink to “本義”">​</a></h3><p>以陽居陰，故有悔。然卦已過中，水火之際，乃革之時，而剛柔不偏，又革之用也，是以悔亡。然又必有孚，然後革乃可獲吉。明佔者有其徳而當其時，又必有信，乃悔亡而得吉也。</p><h3 id="程傳-12" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-12" aria-label="Permalink to “程傳”">​</a></h3><p>九四，革之盛也。陽剛革之才也，離下體而進上體，革之時也。居水火之際，革之勢也，得近君之位，革之任也。下無系應，革之志也。以九居四，剛柔相際，革之用也。四既具此，可謂當革之時也。事之可悔而後革之，革之而當，其悔乃亡也。革之既當，唯在處之以至誠，故有孚則改命吉。改命，改為也，謂革之也。既事當而弊革，行之以誠，上信而下順，其吉可知。四非中正而至善何也？曰：唯其處柔也，故剛而不過，近而不逼，順承中正之君，乃中正之人也。《易》之取義無常也，隨時而已。</p><h3 id="集說-11" tabindex="-1">集說 <a class="header-anchor" href="#集說-11" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>虞氏翻曰 ：將革而謀謂之言，革而行之謂之命。</p></li><li><p>陸氏希聲曰 ：革而當，故悔亡也。為物所信，則命令不便於民者可改易而獲吉。</p></li><li><p>劉氏牧曰 ：成革之體在斯一爻，且自初至三，則革道已成，故下三爻皆以“革”字著於爻辭。至於四，則惟曰“悔亡有孚，改命吉”也。</p></li><li><p>朱子語類 ：問：革下三爻有謹重難改之意，上三爻則革而善。蓋事有新故，下三爻則故事未變之時，必當謹審於其先；上三爻則變而為新事矣。 曰：然，乾卦到九四爻謂“乾道乃革”也，是到這處方變。</p></li><li><p>問：革下三爻有謹重難改之意，上三爻則革而善。蓋事有新故，下三爻則故事未變之時，必當謹審於其先；上三爻則變而為新事矣。 曰：然，乾卦到九四爻謂“乾道乃革”也，是到這處方變。</p></li><li><p>胡氏炳文曰 ：自三至五皆言有孚，三議革而後孚，四有孚而後改，深淺之序也。五未佔而有孚，積孚之素也。</p></li></ul><p>象曰：改命之吉，信志也</p><h3 id="程傳-13" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-13" aria-label="Permalink to “程傳”">​</a></h3><p>改命而吉，以上下信其志也。誠既至，則上下信矣。革之道，以上下之信為本。不當不孚，則不信；當而不信，猶不可行也，況不當乎？</p><h3 id="集說-12" tabindex="-1">集說 <a class="header-anchor" href="#集說-12" aria-label="Permalink to “集說”">​</a></h3><ul><li>龔氏煥曰 ：信志，即有孚之謂。革以有孚為本，信足以孚乎人心，則可以改命而得吉矣。</li></ul><p>九五：大人虎變，未佔有孚</p><h3 id="本義-10" tabindex="-1">本義 <a class="header-anchor" href="#本義-10" aria-label="Permalink to “本義”">​</a></h3><p>虎，大人之象。變，謂希革而毛毨也。在大人，則自新新民之極，順天應人之時也。九五以陽剛中正為革之主，故有此象。佔而得此，則有此應。然亦必自其未佔之時，人已信其如此，乃足以當之耳。</p><h3 id="程傳-14" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-14" aria-label="Permalink to “程傳”">​</a></h3><p>九五以陽剛之才，中正之徳，居尊位，大人也。以大人之道，革天下之事，無不當也，無不時也。所過變化事理炳著，如虎之文采，故云“虎變”。龍虎大人之象也。變者，事物之變。曰虎何也？曰大人變之，乃大人之變也。以大人中正之道變革之，炳然昭著，不待佔決，知其至當，而天下必信也。天下蒙大人之革，不待佔決，知其至當而信之也。</p><h3 id="集說-13" tabindex="-1">集說 <a class="header-anchor" href="#集說-13" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>鄭氏汝諧曰 ：革之道久而後信。五與上，其革之成乎？五陽剛中正，居尊而說體盡，革之羙是以未佔而有孚也。其文曉然見於天下，道徳之威望而可信。若卜筮罔不是孚，虎變之謂也。</p></li><li><p>龔氏煥曰 ：革以孚信為主，故彖與三四皆以孚為言。至五之“未佔有孚”，則不言而信，而無以復加矣。</p></li></ul><p>象曰：大人虎變，其文炳也</p><h3 id="程傳-15" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-15" aria-label="Permalink to “程傳”">​</a></h3><p>事理明著，若虎文之炳煥，明盛也。天下有不孚乎？</p><h3 id="集說-14" tabindex="-1">集說 <a class="header-anchor" href="#集說-14" aria-label="Permalink to “集說”">​</a></h3><ul><li>俞氏琰曰 ：虎之斑文大而疏朗，革道已成，事理簡明，如虎文之炳然也。</li></ul><p>上六：君子豹變，小人革面，徵兇，居貞吉</p><h3 id="本義-11" tabindex="-1">本義 <a class="header-anchor" href="#本義-11" aria-label="Permalink to “本義”">​</a></h3><p>革道已成，君子如豹之變，小人亦革面以聽從矣。不可以往而居正則吉。變革之事，非得已者不可以過，而上六之才亦不可以有行也。故佔者如之。</p><h3 id="程傳-16" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-16" aria-label="Permalink to “程傳”">​</a></h3><p>革之終，革道之成也。君子謂善人良善，則已從革而變，其著見若豹之彬蔚也。小人昏愚難遷者，雖未能心化，亦革其面以從上之教令也。龍虎大人之象，故大人云虎，君子云豹也。人性本善，皆可以變化。然有下愚，雖聖人不能移者。以堯舜為君，以聖繼聖，百有餘年，天下被化，可謂深且久矣。而有苗有象，其來格烝又，蓋亦革面而已。小人既革其外，革道可以為成也。苟更從而深治之，則為已甚，已甚非道也。故至革之終，而又徵則兇也。當貞固以自守，革至於極而不守以貞，則所革隨復變矣。天下之事，始則患乎難革，已革則患乎不能守也。故革之終，戒以居貞則吉也。居貞非為六戒乎？曰：為革終言也，莫不在其中矣。人性本善，有不可革者何也？曰：語其性則皆善也，語其才則有下愚之不移。所謂下愚有二焉，自暴也，自棄也。人苟以善自治，則無不可移者，雖昏愚之至，皆可漸摩而進也。唯自暴者拒之以不信，自棄者絕之以不為，雖聖人與居，不能化而入也。仲尼之所謂下愚也。然天下自棄自暴者，非必皆昏愚也，往往強戾而才力有過人者，商辛是也。聖人以其自絕於善，謂之下愚。然考其歸，則誠愚也。既曰下愚，其能革面何也？曰：心雖絕於善道，其畏威而寡罪，則與人同也。唯其有與人同，所以知其非性之罪也。</p><h3 id="集說-15" tabindex="-1">集說 <a class="header-anchor" href="#集說-15" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>孔氏穎逹曰 ：居革之終，變道已成。君子處之，雖不能同九五革命創制，如虎文之彪炳，然亦潤色鴻業，如豹文之蔚縟。故曰“君子豹變”也。小人革面者，但能變其顏面容色，順上而已。革道已成，宜安靜守正，更有所徵則兇，居而守正則吉。</p></li><li><p>龔氏煥曰 ：九三與上六皆曰“徵兇”，而有“貞厲”、“貞吉”之殊者。三之“徵兇”，戒其不可妄動也；上之“徵兇”，謂事之已革者不可復變也。三當革而未革，故守貞則厲；上已革而當守，故居貞則吉。三革道未成，上革道已成故也。</p></li><li><p>楊氏啟新曰 ：革道已成，非上六革之有革之者也。上六特承其重熙累洽之後，治定功成之日耳。若九五，則必堯舜湯武乃足以當之。首創之君，開大型範，耳目一新，若混沌初闢，其文疏朗闊大；繼體之後，則漸深䆳遒密耳。周之頑民，既歷三紀，世變風移，則“革面”之謂。革而不守以貞，則所變者隨復變矣。天下事未革，患其不能革；既革，患其不能守也。故戒以居貞。</p></li></ul><h3 id="案-2" tabindex="-1">案 <a class="header-anchor" href="#案-2" aria-label="Permalink to “案”">​</a></h3><p>五上兩爻相承，虎豹兩物相似。程傳以君子為被王化之人，似不如孔氏、楊氏以為繼體守成之為安也。如文武開基肇造維新，豈非若虎之變而文采煥然者乎？成康繼世，禮明樂備，豈非若豹之變而文理繁密者乎？言君子雖稍別於大人，然革道必至此而後為詳且備也。至小人革面，方以被王化者言之。所謂“革面”者，亦非但革其面而不能革心之謂，此卦以禽獸取義，凡禽獸之有靈性而近於人者，如猩猩、猿猴之類，皆革其面，故以此為民風丕變之喻。王道之行，則仁義成俗，而心亦無不革矣。不然，何以為必世後仁乎？</p><p>象曰：君子豹變，其文蔚也；小人革面，順以從君也</p><h3 id="程傳-17" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-17" aria-label="Permalink to “程傳”">​</a></h3><p>君子從化遷善，成文彬蔚，章見於外也。中人以上莫不變革，雖不移之小人，則亦不敢肆其惡，革易其外以順從君上之教令，是革面也。至此，革道成矣。小人勉而假善，君子所容也，更往而治之，則兇矣。</p><h3 id="集說-16" tabindex="-1">集說 <a class="header-anchor" href="#集說-16" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>張子曰 ：以柔為德，不及九五剛中炳明，故但文章蔚縟，能使小人改觀而從也。</p></li><li><p>呂氏大臨曰 ：上六與九五皆革道已成之時，虎之文脩大而有理，豹之文密茂而成斑。其文炳然如火之照而易辨也，其文蔚然如草之暢茂而叢聚也。</p></li><li><p>俞氏琰曰 ：小人居革之終，幡然向道以順從君，無不心悅而誠服。或者乃謂面革而心不革，非也。</p></li></ul><p>總論</p><p>龔氏煥曰：初言“鞏用黃牛”，未可有革者也；二言“已日乃革”，不可遽革者也；三言“革言三就”，謹審以為革者也，皆革道之未成也。四言“有孚改命”，則事革矣；五言“大人虎變”，則為聖人之神化矣；上言“君子豹變，小人革面”，則天下為之丕變而革道大成矣。此卦自初至上，明言革道之始終，以及君子、小人之應，可見變革之重要與影響之深遠。革者，非徒求變而已，更在於得其時、得其道、得其人，方能使變革之事得以成功，天下得以治平。</p>',120)])])}const m=e(h,[["render",p]]);export{b as __pageData,m as default};
